'use strict';
const element=id=>document.getElementById(id),params=new URLSearchParams(window.location.search);let active=null,activeScript='',generation=0;
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function show(){const record=active?.records.find(r=>r.path===element('records').value);element('record-name').textContent=record?.path||'No matching record';element('content').textContent=record?.text||'';element('record').disabled=!record;}
function list(preferred){element('records').replaceChildren();const query=element('filter').value.trim().toLowerCase();for(const record of active?.records||[]){if(!record.path.toLowerCase().includes(query))continue;const option=document.createElement('option');option.value=record.path;option.textContent=record.path+' · '+record.bytes+' bytes';element('records').append(option);}if(preferred&&active.records.some(r=>r.path===preferred))element('records').value=preferred;show();}
async function load(script){const revision=++generation;element('status').textContent='Verifying encoded records…';try{const decoded=await globalThis.OstarPublication.decode(script);if(revision!==generation)return;active=decoded;activeScript=script;element('bundle').disabled=false;list(params.get('document'));element('status').textContent=active.records.length+' records verified · '+active.edition.name+' · '+active.edition.guidance;}catch(e){if(revision===generation)element('status').textContent='Publication load failed: '+e.message;}}
element('filter').addEventListener('input',()=>list());element('records').addEventListener('change',show);element('bundle').addEventListener('click',()=>{if(active)download(activeScript,'ostar-'+active.edition.name+'.io');});element('record').addEventListener('click',()=>{const record=active?.records.find(r=>r.path===element('records').value);if(record)download(record.text,record.path.split('/').at(-1).replace(/\.md$/,'.txt'));});
element('import').addEventListener('change',async()=>{const file=element('import').files[0];if(!file)return;if(file.size>10*1024*1024){element('status').textContent='Import exceeds 10 MiB.';return;}const revision=++generation;try{const script=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(revision===generation)await load(script);}catch(e){if(revision===generation)element('status').textContent='Import failed: '+e.message;}});
const edition=params.get('edition');load(globalThis.OstarEncodedEditions[Object.hasOwn(globalThis.OstarEncodedEditions,edition)?edition:'makkakah']);
